<?php
namespace App\Services\Search;
use App\Models\{SoftwareProject,MarketplaceItem,DocumentationPage,User,Organization};
class GlobalSearchService { public function search(string $q,int $limit=8): array { $q=trim($q); if($q==='')return []; return [ 'projects'=>SoftwareProject::where(fn($x)=>$x->where('name','like',"%$q%")->orWhere('tagline','like',"%$q%"))->limit($limit)->get(['id','name','slug','tagline']), 'marketplace'=>MarketplaceItem::where('is_published',true)->where(fn($x)=>$x->where('name','like',"%$q%")->orWhere('summary','like',"%$q%"))->limit($limit)->get(['id','name','slug','summary']), 'documentation'=>DocumentationPage::where('is_published',true)->where(fn($x)=>$x->where('title','like',"%$q%")->orWhere('content','like',"%$q%"))->limit($limit)->get(['id','title','slug','software_project_id']), 'developers'=>User::where('name','like',"%$q%")->limit($limit)->get(['id','name','email']), 'organizations'=>Organization::where('is_public',true)->where('name','like',"%$q%")->limit($limit)->get(['id','name','slug','description']) ]; } }
